SELECT 
  FROM user_identity
 WHERE identity_type = #{identityType}
   AND issuer = #{issuer}
   AND normalized_identifier = #{normalizedIdentifier}
 LIMIT 1

SELECT EXISTS (
    SELECT 1
      FROM user_identity
     WHERE identity_type = #{identityType}
       AND issuer = #{issuer}
       AND normalized_identifier = #{normalizedIdentifier}
)
